INSERT INTO `ai_communication_templates` VALUES (1,1,'tpl_payment_reminder','Payment Reminder','Professional payment reminder for overdue invoices','email','payment','Payment Reminder - Invoice {{invoice_number}}','Dear {{customer_name}},\n\nThis is a friendly reminder that Invoice {{invoice_number}} dated {{invoice_date}} for {{amount}} {{currency}} was due on {{due_date}}.\n\nAs of today, this payment remains outstanding. We kindly request that you arrange payment at your earliest convenience.\n\nIf payment has already been made, please disregard this notice.\n\nPlease find the invoice attached for your reference.\n\nBest regards,\n{{sender_name}}',NULL,'[\"customer_name\",\"invoice_number\",\"invoice_date\",\"amount\",\"currency\",\"due_date\",\"sender_name\"]','professional','en',1,'active',0,NULL,NULL,1,0,'2026-09-10 16:43:39','2026-09-10 16:43:39'),(2,1,'tpl_quotation_followup','Quotation Follow-up','Follow-up on pending quotation','email','quotation','Following Up - Quotation {{quotation_number}}','Dear {{customer_name}},\n\nI wanted to follow up on Quotation {{quotation_number}} that we submitted on {{quotation_date}} for {{amount}} {{currency}}.\n\nWe have not yet received your response and wanted to check if you have any questions or require additional information.\n\nThe quotation is valid until {{valid_until}}.\n\nPlease let us know if you would like to proceed or if there is anything we can adjust.\n\nBest regards,\n{{sender_name}}',NULL,'[\"customer_name\",\"quotation_number\",\"quotation_date\",\"amount\",\"currency\",\"valid_until\",\"sender_name\"]','professional','en',1,'active',0,NULL,NULL,1,0,'2026-09-10 16:43:39','2026-09-10 16:43:39'),(3,1,'tpl_order_confirmation','Order Confirmation','Confirm receipt of purchase order','email','order','Order Confirmation - PO {{order_number}}','Dear {{supplier_name}},\n\nThank you for your Purchase Order {{order_number}} dated {{order_date}}.\n\nWe confirm receipt and acceptance of your order for {{item_count}} item(s) totaling {{amount}} {{currency}}.\n\nEstimated delivery: {{delivery_date}}\n\nWe will notify you when your order has been dispatched.\n\nBest regards,\n{{sender_name}}',NULL,'[\"supplier_name\",\"order_number\",\"order_date\",\"item_count\",\"amount\",\"currency\",\"delivery_date\",\"sender_name\"]','professional','en',1,'active',0,NULL,NULL,1,0,'2026-09-10 16:43:39','2026-09-10 16:43:39'),(4,1,'tpl_shipment_delay','Shipment Delay Notice','Notify about delayed shipment','email','delivery','Important Update - Shipment Delay for Order {{order_number}}','Dear {{customer_name}},\n\nWe regret to inform you that there is a delay in the shipment of your Order {{order_number}}.\n\nOriginal delivery date: {{original_date}}\nRevised delivery date: {{new_date}}\nReason: {{delay_reason}}\n\nWe sincerely apologize for any inconvenience this may cause. Please let us know if you have any questions or concerns.\n\nBest regards,\n{{sender_name}}',NULL,'[\"customer_name\",\"order_number\",\"original_date\",\"new_date\",\"delay_reason\",\"sender_name\"]','apologetic','en',1,'active',0,NULL,NULL,1,0,'2026-09-10 16:43:39','2026-09-10 16:43:39'),(5,1,'tpl_support_response','Support Response','Standard support ticket response','email','support','Re: Support Ticket #{{ticket_number}}','Dear {{customer_name}},\n\nThank you for contacting us regarding {{issue_summary}}.\n\n{{resolution_text}}\n\nIf you have any further questions or if this does not fully resolve your issue, please do not hesitate to reach out.\n\nBest regards,\n{{sender_name}}',NULL,'[\"customer_name\",\"ticket_number\",\"issue_summary\",\"resolution_text\",\"sender_name\"]','friendly','en',1,'active',0,NULL,NULL,1,0,'2026-09-10 16:43:39','2026-09-10 16:43:39'),(6,1,'tpl_supplier_followup','Supplier Follow-up','Follow up with supplier on pending matters','email','procurement','Follow-up - {{subject_summary}}','Dear {{supplier_name}},\n\nI am writing to follow up on {{followup_subject}}.\n\n{{followup_details}}\n\nWe would appreciate your prompt response on this matter.\n\nBest regards,\n{{sender_name}}',NULL,'[\"supplier_name\",\"subject_summary\",\"followup_details\",\"sender_name\"]','firm','en',1,'active',0,NULL,NULL,1,0,'2026-09-10 16:43:39','2026-09-10 16:43:39');
/*!40000 ALTER TABLE `ai_communication_templates` ENABLE KEYS */;
UNLOCK TABLES;

