  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_component` (`component`),
  KEY `idx_status` (`status`),
  KEY `idx_type` (`component_type`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
