INSERT INTO `ai_insight_definitions` VALUES (1,'procurement.overdue_requisitions','Overdue Purchase Requisitions','Detects purchase requisitions that have remained pending beyond a configurable period.','procurement','procurement','hybrid',1,'[\"procurement.view\"]','{\"tool\":\"procurement.search_purchase_requisitions\",\"params\":{\"status\":\"pending\"},\"conditions\":[{\"field\":\"age_days\",\"date_field\":\"created_at\",\"operator\":\"gte\",\"threshold_days\":7}]}','[{\"field\":\"age_days\",\"thresholds\":[{\"min\":1,\"max\":5,\"severity\":\"notice\"},{\"min\":6,\"max\":10,\"severity\":\"warning\"},{\"min\":11,\"severity\":\"critical\"}]}]','{\"resolver\":\"module_managers\"}','{\"route\":\"\\/modules\\/procurement\\/requisitions\\/index.php\",\"label\":\"View Requisitions\"}','same_hash','hourly',100,30,'2026-08-31 09:33:34','2026-08-31 09:45:46'),(2,'procurement.high_pending_volume','High Pending Requisition Volume','Alerts when the number of pending purchase requisitions exceeds a threshold.','procurement','procurement','rule_based',1,'[\"procurement.view\"]','{\"tool\":\"procurement.search_purchase_requisitions\",\"params\":{\"status\":\"pending\"},\"conditions\":[{\"field\":\"count\",\"operator\":\"gte\",\"threshold\":10}]}','[{\"field\":\"count\",\"thresholds\":[{\"min\":10,\"max\":19,\"severity\":\"notice\"},{\"min\":20,\"max\":49,\"severity\":\"warning\"},{\"min\":50,\"severity\":\"critical\"}]}]','{\"resolver\":\"module_managers\"}','{\"route\":\"\\/modules\\/procurement\\/requisitions\\/index.php\",\"label\":\"View Pending Requisitions\"}','same_day','hourly',200,30,'2026-08-31 09:33:34','2026-08-31 09:45:46'),(3,'procurement.po_delays','Purchase Order Delays','Detects purchase orders where expected delivery dates have passed.','procurement','procurement','rule_based',1,'[\"procurement.view\"]','{\"tool\":\"procurement.search_purchase_orders\",\"params\":{\"status\":\"open\"},\"conditions\":[{\"field\":\"age_days\",\"date_field\":\"expected_delivery_date\",\"operator\":\"gte\",\"threshold_days\":0}]}','[{\"field\":\"age_days\",\"thresholds\":[{\"min\":1,\"max\":3,\"severity\":\"info\"},{\"min\":4,\"max\":7,\"severity\":\"notice\"},{\"min\":8,\"max\":14,\"severity\":\"warning\"},{\"min\":15,\"severity\":\"critical\"}]}]','{\"resolver\":\"module_managers\"}','{\"route\":\"\\/modules\\/procurement\\/purchase_orders\\/index.php\",\"label\":\"View Purchase Orders\"}','same_hash','daily',100,30,'2026-08-31 09:33:34','2026-08-31 09:45:46'),(4,'procurement.supplier_concentration','Supplier Concentration','Analytical insight showing when a high percentage of purchase orders involve a single supplier.','procurement','procurement','hybrid',1,'[\"procurement.view\"]','{\"tool\":\"procurement.search_purchase_orders\",\"params\":{\"status\":\"open\"},\"conditions\":[{\"field\":\"percentage\",\"group_field\":\"vendor_id\",\"operator\":\"gte\",\"threshold\":50}]}','[{\"field\":\"percentage\",\"thresholds\":[{\"min\":50,\"max\":64,\"severity\":\"info\"},{\"min\":65,\"max\":79,\"severity\":\"notice\"},{\"min\":80,\"severity\":\"warning\"}]}]','{\"resolver\":\"module_managers\"}','{\"route\":\"\\/modules\\/procurement\\/purchase_orders\\/index.php\",\"label\":\"View Purchase Orders\"}','same_day','daily',200,30,'2026-08-31 09:33:34','2026-08-31 09:45:46');
