INSERT INTO `ai_observability_spans` VALUES (7,124,'trace_3249166895630874','span_4f0e64ae1a83cd0c',NULL,'context_retrieval','ERP Context Retrieval','ai_chat',NULL,'2026-09-02 08:18:41','2026-09-02 08:18:41',0,'success',NULL,NULL,'ERP and navigation context prepared.','[]','2026-09-02 08:18:41','2026-09-02 08:18:41'),(8,124,'trace_3249166895630874','span_abc055e595c28e91',NULL,'knowledge_search','Knowledge Search','ai_chat',NULL,'2026-09-02 08:18:41','2026-09-02 08:18:41',0,'success',NULL,NULL,'No relevant company knowledge found.','{\"matches\":0}','2026-09-02 08:18:41','2026-09-02 08:18:41'),(9,124,'trace_3249166895630874','span_0c5bfdd20e343b72',NULL,'response_generation','Provider Response Generation','ai_chat',NULL,'2026-09-02 08:18:41','2026-09-02 08:18:44',0,'success',NULL,NULL,'Hello! 👋 Welcome to the ERP system. I\'m here to help you with anything you need — whether it\'s navigating modules, understanding processes, or answering questions about your data.\n\nHere\'s a quick overview of what I can assist with:\n\n- **Procurement** — Requisitions, purchase orders, RFQs, and suppliers\n- **Finance** — Invoices, payments, and financial management\n- **HRMS** — Employees, attendance, and leave\n- **CRM** — Customers, leads, and deals\n- **Helpdesk** — Support tickets and SLAs\n- **AI** — AI assistants, models, automations, and more\n- **Reports & Analytics** — Business reports and dashboards\n\nHow can I help you today?','{\"iteration\":1,\"supports_tools\":false,\"tool_call_count\":0,\"input_tokens\":\"[masked]\",\"output_tokens\":\"[masked]\"}','2026-09-02 08:18:41','2026-09-02 08:18:44'),(10,125,'trace_f7e40566e470ad55','span_37c65288749b33e7',NULL,'context_retrieval','ERP Context Retrieval','ai_chat',NULL,'2026-09-02 08:19:03','2026-09-02 08:19:03',0,'success',NULL,NULL,'ERP and navigation context prepared.','[]','2026-09-02 08:19:03','2026-09-02 08:19:03'),(11,125,'trace_f7e40566e470ad55','span_ea937aee916b939b',NULL,'knowledge_search','Knowledge Search','a