INSERT INTO `ai_workflow_templates` VALUES (1,'event_condition_notification','Event -> Condition -> Notification','React to an ERP event and notify a responsible user.','system','event','{\"nodes\":[{\"id\":\"trigger_1\",\"type\":\"event_trigger\",\"name\":\"Trigger\",\"config\":{\"event_name\":\"procurement.requisition.created\",\"filters\":[]}},{\"id\":\"condition_1\",\"type\":\"field_condition\",\"name\":\"Condition\",\"config\":{\"field\":\"status\",\"operator\":\"equals\",\"value\":\"Pending\"}},{\"id\":\"notify_1\",\"type\":\"notification\",\"name\":\"Notify\",\"config\":{\"recipient_resolver\":\"workflow_owner\",\"title_template\":\"Workflow Alert: {{workflow.name}}\",\"summary_template\":\"Condition matched for record {{record_id}}.\",\"severity\":\"medium\"}},{\"id\":\"end_1\",\"type\":\"end\",\"name\":\"End\",\"config\":[]}],\"edges\":[{\"from\":\"trigger_1\",\"to\":\"condition_1\",\"label\":\"next\"},{\"from\":\"condition_1\",\"to\":\"notify_1\",\"label\":\"yes\"},{\"from\":\"notify_1\",\"to\":\"end_1\",\"label\":\"next\"}]}',1,'2026-09-01 11:07:04'),(2,'schedule_read_ai_notification','Schedule -> Read Tool -> AI Summary -> Notification','Run on a schedule, read ERP data, summarize it, then notify users.','system','scheduled','{\"nodes\":[{\"id\":\"trigger_1\",\"type\":\"schedule_trigger\",\"name\":\"Trigger\",\"config\":{\"schedule_type\":\"daily\",\"time\":\"09:00\",\"timezone\":\"Asia\\/Dubai\"}},{\"id\":\"condition_1\",\"type\":\"field_condition\",\"name\":\"Condition\",\"config\":{\"field\":\"status\",\"operator\":\"equals\",\"value\":\"Pending\"}},{\"id\":\"notify_1\",\"type\":\"notification\",\"name\":\"Notify\",\"config\":{\"recipient_resolver\":\"workflow_owner\",\"title_template\":\"Workflow Alert: {{workflow.name}}\",\"summary_template\":\"Condition matched for record {{record_id}}.\",\"severity\":\"medium\"}},{\"id\":\"end_1\",\"type\":\"end\",\"name\":\"End\",\"config\":[]}],\"edges\":[{\"from\":\"trigger_1\",\"to\":\"condition_1\",\"label\":\"next\"},{\"from\":\"condition_1\",\"to\":\"notify_1\",\"label\":\"yes\"},{\"from\":\"notify_1\",\"to\":\"end_1\",\"label\":\"next\"}]}',1,'2026-09-01 11:07:04'),(3,'event_condition_task','Event -> Condition -> Create Task','Create follow-up work when an event meets a threshold.','system','event','{\"nodes\":[{\"id\":\"trigger_1\",\"type\":\"event_trigger\",\"name\":\"Event Trigger\",\"config\":{\"event_name\":\"procurement.requisition.created\",\"filters\":[]}},{\"id\":\"condition_1\",\"type\":\"threshold_condition\",\"name\":\"Age Threshold\",\"config\":{\"metric\":\"age_days\",\"operator\":\"greater_than_or_equal\",\"value\":7}},{\"id\":\"task_1\",\"type\":\"create_task\",\"name\":\"Create Task\",\"config\":{\"title_template\":\"Review overdue requisition\",\"description_template\":\"Workflow created a follow-up for requisition {{record_id}}.\",\"assignee_resolver\":\"procurement_manager\"}},{\"id\":\"end_1\",\"type\":\"end\",\"name\":\"End\",\"config\":[]}],\"edges\":[{\"from\":\"trigger_1\",\"to\":\"condition_1\",\"label\":\"next\"},{\"from\":\"condition_1\",\"to\":\"task_1\",\"label\":\"yes\"},{\"from\":\"task_1\",\"to\":\"end_1\",\"label\":\"next\"}]}',1,'2026-09-01 11:07:04'),(4,'manual_analysis_report','Manual -> Read Tool -> Analysis -> Report','Run manually for a controlled operational review.','system','manual','{\"nodes\":[{\"id\":\"trigger_1\",\"type\":\"manual_trigger\",\"name\":\"Manual Trigger\",\"config\":{\"label\":\"Run manually\"}},{\"id\":\"tool_1\",\"type\":\"read_tool\",\"name\":\"Read Tool\",\"config\":{\"tool_id\":\"procurement.search_purchase_requisitions\",\"input\":{\"status\":\"pending_approval\"}}},{\"id\":\"analysis_1\",\"type\":\"ai_analysis\",\"name\":\"Analysis\",\"config\":{\"analysis_type\":\"classify_urgency\",\"field\":\"status\"}},{\"id\":\"notify_1\",\"type\":\"notification\",\"name\":\"Notify\",\"config\":{\"recipient_resolver\":\"workflow_owner\",\"title_template\":\"Manual workflow review completed\",\"summary_template\":\"Review completed for workflow {{workflow.name}}.\",\"severity\":\"low\"}},{\"id\":\"end_1\",\"type\":\"end\",\"name\":\"End\",\"config\":[]}],\"edges\":[{\"from\":\"trigger_1\",\"to\":\"tool_1\",\"label\":\"next\"},{\"from\":\"tool_1\",\"to\":\"analysis_1\",\"label\":\"next\"},{\"from\":\"analysis_1\",\"to\":\"notify_1\",\"label\":\"next\"},{\"from\":\"notify_1\",\"to\":\"end_1\",\"label\":\"next\"}]}',1,'2026-09-01 11:07:04'),(5,'event_human_approval_action','Event -> Human Approval -> Action','Pause for human approval before a follow-up action.','system','event','{\"nodes\":[{\"id\":\"trigger_1\",\"type\":\"event_trigger\",\"name\":\"Event Trigger\",\"config\":{\"event_name\":\"procurement.requisition.created\",\"filters\":[]}},{\"id\":\"approval_1\",\"type\":\"approval_request\",\"name\":\"Approval\",\"config\":{\"title_template\":\"Workflow approval required\",\"summary_template\":\"Please review workflow {{workflow.name}} for record {{record_id}}.\",\"approver_resolver\":\"procurement_manager\"}},{\"id\":\"end_1\",\"type\":\"end\",\"name\":\"End\",\"config\":[]}],\"edges\":[{\"from\":\"trigger_1\",\"to\":\"approval_1\",\"label\":\"next\"},{\"from\":\"approval_1\",\"to\":\"end_1\",\"label\":\"yes\"}]}',1,'2026-09-01 11:07:04');
